// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient1, uint256 amount1, address recipient2, uint256 amount2) public {
        vm.assume(recipient1 != address(0));
        vm.assume(recipient2 != address(0));
        c.newGrantProposal(recipient1, amount1);
        c.newGrantProposal(recipient2, amount2);
        uint256 count = c.proposalCount();
        (address rPrev, uint256 aPrev) = c.mapPID_grant(count - 1);
        (address rLast, uint256 aLast) = c.mapPID_grant(count);
        assertTrue(rPrev == recipient1 && aPrev == amount1 && rLast == recipient2 && aLast == amount2);
    }
}
